        nums = [int(x) for x in re.findall(r'\d+', s)]
        day = next((n for n in nums if 1 <= n <= 31), 0)
        year = next((n for n in nums if n > 31), 0)
        if day:
            y = year or today.year
            try:
                x = datetime.date(y, mi + 1, day)
            except ValueError:
                return ''
            if not year and x < today:
                x = datetime.date(y + 1, mi + 1, day)
            return x.isoformat()
    return ''


def _tokens(text):
    return [t for t in re.split(r'[^0-9a-z]+', str(text or '').lower()) if t]


def _parse_number(tokens, i):
    # One English number. A following number word starts a new value, so fifteen then fifteen stays two parts.
    if i >= len(tokens) or tokens[i] not in _ONES and tokens[i] not in _TENS and tokens[i] not in ('hundred', 'thousand'):
        return None
    start = i
    total = 0
    current = None
    while i < len(tokens):
        w = tokens[i]
        if w == 'and':
            if current is None and total == 0:
                break
            i += 1
            continue
        if w in _ONES:
            n = _ONES[w]
            if current is None:
                current = n
            elif current >= 100 and current % 100 == 0 or (current >= 20 and current % 10 == 0 and n < 10):
                current += n
            else:
                break
            i += 1
            continue
        if w in _TENS:
            if current is None:
                current = _TENS[w]
            elif current >= 100 and current % 100 == 0:
                current += _TENS[w]
            else:
                break
            i += 1
            continue
        if w == 'hundred':
            current = (1 if current is None else current) * 100
            i += 1
            continue
        if w == 'thousand':
            current = (1 if current is None else current) * 1000
            total += current
            current = None
            i += 1
            continue
        break
    if i == start or (current is None and total == 0):
        return None
    return total + (0 if current is None else current), i


def assemble_spoken(text):
    # (value, partial, spelled). partial is one piece. spelled is digit-by-digit or one word at a time.
    raw = str(text or '').strip()
    bare = raw.replace(',', '')
    if re.fullmatch(r'-?\d+(?:\.\d+)?', bare):
        one = len(re.sub(r'\D', '', bare)) <= 1
        return bare, one, one
    tokens = _tokens(raw)
    if not tokens:
        return '', True, True
    groups = []
    spelled = True
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if tok == 'and':
            i += 1
            continue
        if tok.isdigit():
            groups.append(tok)
            if len(tok) != 1:
                spelled = False
            i += 1
            continue
        parsed = _parse_number(tokens, i)
        if parsed is not None:
            value, nxt = parsed
            groups.append(str(int(value)))
            if nxt - i != 1:
                spelled = False
            i = nxt
            continue
        if len(tok) == 1 and tok.isalpha():
            groups.append(tok.upper())
            i += 1
            continue
        groups.append(tok.upper())
        spelled = False
        i += 1
    partial = spelled and len(tokens) == 1
    return ''.join(groups), partial, spelled


def clean_spoken(kind, text, today):
    s = str(text or '').strip()
    if kind == 'date':
        iso = to_iso(s, datetime.date(today.year, 1, 1))
        if iso:
            y = int(iso[:4])
            if y > today.year:  # a birth date has no future year; to_iso rolled it
                iso = str(y - 1) + iso[4:]
            return iso, False
        return s, False
    value, partial, spelled = assemble_spoken(s)
    if kind == 'year':
        m = re.search(r'(1[89]|20)\d\d', s)
        if m:
            return m.group(0), False
        digits = re.sub(r'\D', '', value)
        return (digits if digits else re.sub(r'\D', '', s)), partial
    if kind == 'digits':
        digits = re.sub(r'\D', '', value)
        if not digits:
            digits = re.sub(r'\D', '', s)
        return digits, partial
    if kind == 'code':
        if spelled:
            return re.sub(r'[^A-Za-z0-9]', '', value).upper(), partial
        return re.sub(r'\s+', ' ', s).upper(), False
    return re.sub(r'\s+', ' ', s), False


def join_piece(previous, cleaned, partial):
    # Stick the next spoken piece onto the piece already heard. A finished value replaces it.
    previous = str(previous or '')
    cleaned = str(cleaned or '')
    if not partial:
        return cleaned, ''
    if previous and cleaned.startswith(previous) and len(cleaned) > len(previous):
        return cleaned, cleaned
    if previous:
        assembled = (previous + cleaned)[:24]
        return assembled, assembled
    return cleaned, cleaned

try:
    CFG = json.loads("{\"id_fields\": {\"answer\": \"answer\", \"field\": \"field\"}, \"identity\": {\"kinds\": {\"date_of_birth\": \"date\", \"phone_last4\": \"digits\"}, \"max_wrong\": 3, \"prompts\": {\"date_of_birth\": \"What is your date of birth?\", \"phone_last4\": \"What are the last four digits of the phone number we have on file for you?\"}, \"questions\": [\"date_of_birth\", \"phone_last4\"], \"swap_hint\": true} }")
    b = config.get('body') or dict()
    F = CFG['id_fields']
    q = str(b.get(F['field']) or '')
    kind = CFG['identity']['kinds'].get(q, 'text')
    today = parse_now(vars.get('now')).date()
    cleaned, partial = clean_spoken(kind, b.get(F['answer']), today)
    if str(vars.get('id_piece_field') or '') != q:
        vars['id_piece'] = ''
    vars['id_piece_field'] = q
    assembled, stored = join_piece(vars.get('id_piece'), cleaned, partial)
    vars['id_piece'] = stored
    vars['id_partial'] = 'yes' if partial else 'no'
    b[F['answer']] = assembled
    vars['id_last_field'] = q
    config['body'] = b
except Exception as _err:
    pass
    vars['tcc_error'] = str(_err)[:300]

