multi\": false, \"outcome_map\": {\"np_dispute\": [\"no_promise\", \"dispute\"], \"np_hardship\": [\"no_promise\", \"hardship\"], \"np_refused\": [\"no_promise\", \"refused\"], \"np_service_error\": [\"no_promise\", \"service_error\"], \"nr_callback\": [\"not_reached\", \"callback\"], \"nr_deceased\": [\"not_reached\", \"deceased\"], \"nr_no_callback\": [\"not_reached\", \"no_callback\"], \"nr_unclear\": [\"not_reached\", \"unclear\"], \"nr_wrong_number\": [\"not_reached\", \"wrong_number\"], \"nv_declined\": [\"not_verified\", \"declined\"], \"nv_failed\": [\"not_verified\", \"failed\"], \"paid\": [\"paid\", null], \"promise\": [\"promise\", null], \"tr_human\": [\"transferred\", \"human\"], \"tr_restructuring\": [\"transferred\", \"restructuring\"], \"tr_support\": [\"transferred\", \"support\"]}, \"retries\": {\"close_call\": 1, \"create_promise\": 1, \"get_account\": 1, \"schedule_callback\": 1, \"transfer_to_agent\": 1, \"verify_identity\": 1} }")
