import datetime
import json
import re

FALLBACK_KEY = {'nr_no_callback': 'nr_unclear', 'nr_callback': 'nr_unclear', 'nr_wrong_number': 'nr_unclear',
                'nr_deceased': 'nr_unclear', 'nv_declined': 'nv_failed', 'nv_failed': 'nr_unclear',
                'np_hardship': 'np_refused', 'np_dispute': 'np_refused', 'np_service_error': 'np_refused',
                'paid': 'np_refused', 'tr_support': 'np_hardship', 'tr_human': 'np_refused',
                'tr_restructuring': 'np_refused', 'np_refused': 'nr_unclear', 'promise': 'np_refused'}
STATUS_KEY = {'refused': 'np_refused', 'hardship': 'np_hardship', 'dispute': 'np_dispute', 'paid': 'paid',
              'service_error': 'np_service_error', 'open': 'np_refused'}

def num(v):
    if isinstance(v, bool):
        return 0.0
    if isinstance(v, (int, float)):
        return float(v)
    s = re.sub(r'[^0-9.,\-]', '', str(v or ''))
    if s.count(',') and s.count('.'):
        s = s.replace(',', '')
    elif s.count(',') == 1 and len(s.split(',')[1]) == 2:
        s = s.replace(',', '.')
    else:
        s = s.replace(',', '')
    return float(s) if s not in ('', '.', '-') else 0.0


def truthy(v):
    return str(v).strip().lower() in ('true', '1', 'yes')


def jget(vars, key, default):
    v = vars.get(key)
    if isinstance(v, (dict, list)):
        return v
    try:
        x = json.loads(v) if isinstance(v, str) and v.strip() else None
    except ValueError:
        x = None
    return x if isinstance(x, type(default)) else default


def jput(vars, key, value):
    vars[key] = json.dumps(value)


def outcome_fields(cfg, key):
    om = cfg.get('outcome_map') or dict()
    seen = set()
    k = key
    while k and k not in seen:
        seen.add(k)
        v = om.get(k)
        if v:
            return k, v[0], v[1]
        k = FALLBACK_KEY.get(k)
    return key, '', None


def final_key(vars, cfg):
    tr = str(vars.get('transfer_key') or '')
    if tr and tr != 'none':
        return 'tr_' + tr
    if str(vars.get('end_key') or '') == 'np_service_error_hard':
        return 'np_service_error'
    if str(vars.get('phase') or '') != 'products':
        return str(vars.get('end_key') or 'nr_unclear')
    pst = jget(vars, 'pstate', dict())
    order = jget(vars, 'pids', [])
    statuses = [pst.get(p, 'open') for p in order]
    if not statuses:
        return str(vars.get('end_key') or 'np_refused')
    if 'promised' in statuses:
        return 'promise'
    statuses = ['refused' if s == 'open' else s for s in statuses]
    if not cfg.get('multi') or len(statuses) == 1:
        return STATUS_KEY.get(statuses[0], 'np_refused')
    if all(s == 'paid' for s in statuses):
        return 'paid'
    rule = cfg.get('close_rule') or dict()
    if rule.get('kind') == 'priority' and rule.get('order'):
        for k in rule['order']:
            if k in statuses:
                return STATUS_KEY.get(k, 'np_refused')
    for s in statuses:
        if s != 'paid':
            return STATUS_KEY.get(s, 'np_refused')
    return 'np_refused'


def refresh_close(vars, cfg):
    key, outcome, reason = outcome_fields(cfg, final_key(vars, cfg))
    vars['close_key'] = key
    vars['close_outcome'] = outcome or ''
    vars['close_reason'] = reason or ''
    vars['close_code'] = outcome or ''
    return key


def open_pids(vars):
    pst = jget(vars, 'pstate', dict())
    return [p for p in jget(vars, 'pids', []) if pst.get(p, 'open') == 'open']


def set_status(vars, pid, status):
    pst = jget(vars, 'pstate', dict())
    if pid in jget(vars, 'pids', []) and (pst.get(pid) != 'promised' or status == 'promised'):
        pst[pid] = status  # a recorded promise is never downgraded
        jput(vars, 'pstate', pst)


def neg_flag(vars):
    vars['neg_state'] = 'done' if not open_pids(vars) else 'open'
    return vars['neg_state']

# MSG-BEGIN
MSG = {"dup": "This product already has a recorded promise. Do not call create_promise for it again.", "failed": "It did not go through a second time. Do not try again. Tell the customer you could not save it because of a technical problem.", "more": "If another agreed promise is not recorded yet, CALL create_promise for it now; otherwise continue with the next open product.", "recorded": "The promise is recorded.", "retry": "A technical problem stopped this; it did not go through. Do not ask the customer again: say in a few words that there was a technical problem and you are trying again, and CALL create_promise once more now with the same values. Do not use the word recorded."}
# MSG-END

try:
    CFG = json.loads("{\"close_rule\": {\"kind\": \"single\"}, \"multi\": false, \"outcome_map\": {\"np_dispute\": [\"no_promise\", \"dispute\"], \"np_hardship\": [\"no_promise\", \"hardship\"], \"np_refused\": [\"no_promise\", \"refused\"], \"np_service_error\": [\"no_promise\", \"service_error\"], \"nr_callback\": [\"not_reached\", \"callback\"], \"nr_deceased\": [\"not_reached\", \"deceased\"], \"nr_no_callback\": [\"not_reached\", \"no_callback\"], \"nr_unclear\": [\"not_reached\", \"unclear\"], \"nr_wrong_number\": [\"not_reached\", \"wrong_number\"], \"nv_declined\": [\"not_verified\", \"declined\"], \"nv_failed\": [\"not_verified\", \"failed\"], \"paid\": [\"paid\", null], \"promise\": [\"promise\", null], \"tr_human\": [\"transferred\", \"human\"], \"tr_restructuring\": [\"transferred\", \"restructuring\"], \"tr_support\": [\"transferred\", \"support\"]}, \"retries\": {\"close_call\": 1, \"create_promise\": 1, \"get_account\": 1, \"schedule_callback\": 1, \"transfer_to_agent\": 1, \"verify_identity\": 1} }")
    result.pop('header', None)
    d = result.get('data') if isinstance(result.get('data'), dict) else dict()
    pid = str(vars.get('cp_pid') or '')
    if jget(vars, 'pstate', dict()).get(pid) == 'promised':
        d['what_to_do_next'] = MSG['dup'] + (' ' + MSG['more'] if open_pids(vars) else '')
    elif truthy(d.get('ok')):
        set_status(vars, pid, 'promised')
        vars['promises_n'] = str(int(num(vars.get('promises_n'))) + 1)
        d['what_to_do_next'] = MSG['recorded'] + (' ' + MSG['more'] if open_pids(vars) else '')
    else:
        fails = jget(vars, 'cp_fails', dict())
        n = int(fails.get(pid, 0)) + 1
        fails[pid] = n
        jput(vars, 'cp_fails', fails)
        if n <= int(CFG['retries'].get('create_promise', 1)):
            d['what_to_do_next'] = MSG['retry']
        else:
            set_status(vars, pid, 'service_error')
            d['what_to_do_next'] = MSG['failed'] + (' ' + MSG['more'] if open_pids(vars) else '')
    result['data'] = d
    neg_flag(vars)
    refresh_close(vars, CFG)
except Exception as _err:
    pass
    vars['tcc_error'] = str(_err)[:300]

