def neg_flag(vars):
    vars['neg_state'] = 'done' if not open_pids(vars) else 'open'
    return vars['neg_state']

# MSG-BEGIN
MSG = {"dup": "This product already has a recorded promise. Do not call create_promise for it again.", "failed": "It did not go through a second time. Do not try again. Tell the customer you could not save it because of a technical problem.", "more": "If another agreed promise is not recorded yet, CALL create_promise for it now; otherwise continue with the next open product.", "recorded": "The promise is recorded.", "retry": "A technical problem stopped this; it did not go through. Do not ask the customer again: say in a few words that there was a technical problem and you are trying again, and CALL create_promise once more now with the same values. Do not use the word recorded."}
# MSG-END

try:
