def num(v):
    if isinstance(v, bool):
        return 0.0
    if isinstance(v, (int, float)):
        return float(v)
    s = re.sub(r'[^0-9.,\-]', '', str(v or ''))
    if s.count(',') and s.count('.'):
        s = s.replace(',', '')
    elif s.count(',') == 1 and len(s.split(',')[1]) == 2:
        s = s.replace(',', '.')
    else:
