    CFG = json.loads("{\"close_rule\": {\"kind\": \"single\"}, \"closing_prefix\": {\"np_service_error\": \"I am sorry, I could not complete that because of a system problem.\", \"nr_callback\": \"Thank you, we will call back then.\", \"nr_deceased\": \"I am sorry for your loss.\", \"nr_wrong_number\": \"Sorry for the trouble.\", \"nv_failed\": \"I cannot continue; please visit a branch or use online banking.\", \"paid\": \"Payments can take one business day to appear.\", \"promise\": \"A confirmation of this promise will be sent to you by text message.\", \"tr_human\": \"I am connecting you with a colleague now.\", \"tr_restructuring\": \"I am connecting you with a colleague now.\", \"tr_support\": \"I am connecting you with our support team now.\"}, \"lines\": {\"ai\": \"I am Nordhavn Bank's virtual assistant.\", \"ask_again\": \"Sorry, just to be sure: am I speaking with { {title} } { {last_name} }?\", \"cannot_record\": \"I am sorry, I could not record the promise.\", \"change_promise\": \"A recorded promise cannot be changed or cancelled in this call.\", \"condolence\": \"I am sorry for your loss.\", \"confirm_question\": \"Do you confirm?\", \"debt_intro\": \"I am calling from the collections team about a late payment.\", \"failed_id\": \"I cannot continue; please visit a branch or use online banking.\", \"first_ask\": \"Can you make this payment today?\", \"first_ask_multi\": \"Can you make this payment today?\", \"goodbye\": \"Thank you for your time, goodbye.\", \"hardship_sympathy\": \"I am sorry to hear that.\", \"hint_retry\": \"Could you please say the month as a word?\", \"id_reason\": \"These questions are there to protect your account.\", \"no_info\": \"I do not have that information.\", \"opening\": \"Hello, I am a virtual assistant from Nordhavn Bank, and this call is recorded.\", \"paid_reply\": \"Payments can take one business day to appear.\", \"promise_confirmation\": \"A confirmation of this promise will be sent to you by text message.\", \"right_party_question\": \"Am I speaking with { {title} } { {last_name} }?\", \"scam\": \"You can verify this call by phoning the number on the back of your card or on nordhavn.example.\"}, \"multi\": false, \"note_map\": {}, \"notes\": false, \"outcome_map\": {\"np_dispute\": [\"no_promise\", \"dispute\"], \"np_hardship\": [\"no_promise\", \"hardship\"], \"np_refused\": [\"no_promise\", \"refused\"], \"np_service_error\": [\"no_promise\", \"service_error\"], \"nr_callback\": [\"not_reached\", \"callback\"], \"nr_deceased\": [\"not_reached\", \"deceased\"], \"nr_no_callback\": [\"not_reached\", \"no_callback\"], \"nr_unclear\": [\"not_reached\", \"unclear\"], \"nr_wrong_number\": [\"not_reached\", \"wrong_number\"], \"nv_declined\": [\"not_verified\", \"declined\"], \"nv_failed\": [\"not_verified\", \"failed\"], \"paid\": [\"paid\", null], \"promise\": [\"promise\", null], \"tr_human\": [\"transferred\", \"human\"], \"tr_restructuring\": [\"transferred\", \"restructuring\"], \"tr_support\": [\"transferred\", \"support\"]} }")
